"""fx3std: the FluidXPro3 standard library for Python code generated by fx3c.

Every name here matches fx3c/stdlib.py. Names that clash with Python built-ins get a
trailing underscore, the same way the code generator spells them (Random.int -> int_).
Only the Python standard library is used, except Ai (the `anthropic` package).
"""

from __future__ import annotations

import csv
