from urllib import error as _urlerror
from urllib import parse as _urlparse
from urllib import request as _urlrequest

import fx3rt as _rt


# ---------------------------------------------------------------------------
# secrets.env: loaded when a generated program starts (the environment wins)
# ---------------------------------------------------------------------------

def _load_secrets() -> None:
    starts = [_P.cwd(), _P(sys.argv[0]).resolve().parent if sys.argv and sys.argv[0] else _P.cwd()]
    for start in starts:
        for folder in [start, *start.parents]:
            f = folder / "secrets.env"
            if f.is_file():
                for raw in f.read_text(encoding="utf-8").splitlines():
                    line = raw.strip()
                    if not line or line.startswith("#") or "=" not in line:
                        continue
                    if line.startswith("export "):
                        line = line[7:].strip()
                    k, v = line.split("=", 1)
                    k, v = k.strip(), v.strip()
                    if len(v) >= 2 and v[0] == v[-1] and v[0] in "\"'":
                        v = v[1:-1]
                    if k and v and not os.environ.get(k):
                        os.environ[k] = v
                    if k:
                        _rt.add_secret(os.environ.get(k))      # everything in secrets.env is a secret
                return


_load_secrets()


# ---------------------------------------------------------------------------
# Math
# ---------------------------------------------------------------------------

class Math:
    pi = math.pi
    e = math.e
    tau = math.tau
    inf = math.inf

    @staticmethod
    def sqrt(x):
        if x < 0:
            raise _rt.Panic(f"sqrt of a negative number ({_rt.show(x)})")
        return math.sqrt(x)

    @staticmethod
    def pow(base, exponent):  # noqa: A003
        try:
            return math.pow(base, exponent)
        except OverflowError:
            return math.inf
        except ValueError:
            raise _rt.Panic(f"pow({_rt.show(base)}, {_rt.show(exponent)}) has no real result") from None

    @staticmethod
    def _positive(x, name):
        if x <= 0:
            raise _rt.Panic(f"{name} of {_rt.show(x)} (it must be more than 0)")

    @staticmethod
    def log(x):
        Math._positive(x, "log")
        return math.log(x)

    @staticmethod
    def log10(x):
        Math._positive(x, "log10")
        return math.log10(x)

    @staticmethod
    def log2(x):
        Math._positive(x, "log2")
        return math.log2(x)

    @staticmethod
    def exp(x):
        try:
            return math.exp(x)
        except OverflowError:
            return math.inf

    sin = staticmethod(math.sin)
    cos = staticmethod(math.cos)
    tan = staticmethod(math.tan)
    atan = staticmethod(math.atan)
    atan2 = staticmethod(math.atan2)

    @staticmethod
    def hypot(a, b):
        return math.hypot(a, b)

    @staticmethod
    def asin(x):
        if not -1 <= x <= 1:
            raise _rt.Panic(f"asin of {_rt.show(x)} (it must be between -1 and 1)")
        return math.asin(x)

    @staticmethod
    def acos(x):
        if not -1 <= x <= 1:
            raise _rt.Panic(f"acos of {_rt.show(x)} (it must be between -1 and 1)")
        return math.acos(x)

    @staticmethod
    def clamp(value, low, high):
        if low > high:
            raise _rt.Panic(f"clamp: low ({_rt.show(low)}) is more than high ({_rt.show(high)})")
        return low if value < low else high if value > high else value

    @staticmethod
    def lerp(a, b, t):
        return a + (b - a) * t

    @staticmethod
    def gcd(a, b):
        return math.gcd(a, b)

    @staticmethod
    def lcm(a, b):
        return _rt.i64(abs(a * b) // math.gcd(a, b)) if a and b else 0

    @staticmethod
    def isPrime(n):
        if n < 2:
            return False
        if n % 2 == 0:
            return n == 2
        k = 3
        while k * k <= n:
            if n % k == 0:
                return False
            k += 2
        return True

    @staticmethod
    def factorial(n):
        if n < 0:
            raise _rt.Panic("factorial of a negative number")
        return _rt.i64(math.factorial(n))


# ---------------------------------------------------------------------------
# Random
# ---------------------------------------------------------------------------

class Random:
    _rng = _random.Random()

    @staticmethod
    def int_(low, high):
        if low > high:
            raise _rt.Panic(f"Random.int: low ({low}) is more than high ({high})")
        return Random._rng.randint(low, high)

    @staticmethod
    def float_():
        return Random._rng.random()

    @staticmethod
    def chance(probability):
        return Random._rng.random() < probability

    @staticmethod
    def pick(items):
        pool = list(items.keys()) if isinstance(items, dict) else sorted(items) if isinstance(items, set) else list(items)
        if not pool:
            raise _rt.Panic("Random.pick from an empty collection")
        return Random._rng.choice(pool)

    @staticmethod
    def shuffle(items):
        Random._rng.shuffle(items)

    @staticmethod
    def seed(n):
        Random._rng.seed(n)


# ---------------------------------------------------------------------------
# Time
# ---------------------------------------------------------------------------

_TIME_TOKENS = re.compile(r"YYYY|MMMM|MMM|MM|DD|dddd|ddd|HH|mm|ss")
_TIME_MAP = {"YYYY": "%Y", "MMMM": "%B", "MMM": "%b", "MM": "%m", "DD": "%d", "dddd": "%A", "ddd": "%a",
             "HH": "%H", "mm": "%M", "ss": "%S"}


def _strftime_pattern(pattern: str) -> str:
    return _TIME_TOKENS.sub(lambda m: _TIME_MAP[m.group(0)], pattern.replace("%", "%%"))


class Time:
    __slots__ = ("_dt",)

    def __init__(self, dt: datetime):
        self._dt = dt

    @staticmethod
    def now():
        return Time(datetime.now().replace(microsecond=datetime.now().microsecond // 1000 * 1000))

    @staticmethod
    def today():
        d = datetime.now()
        return Time(datetime(d.year, d.month, d.day))

    @staticmethod
    def of(year, month, day, hour=0, minute=0, second=0):
        try:
            return Time(datetime(year, month, day, hour, minute, second))
        except ValueError as e:
            raise _rt.ValueError(f"not a real date/time: {e}") from None

    @staticmethod
    def parse(text, format_="YYYY-MM-DD"):
        try:
            return Time(datetime.strptime(text.strip(), _strftime_pattern(format_)))
        except ValueError:
            raise _rt.ParseError(f"'{text}' doesn't match the format {format_}") from None

    @staticmethod
    def since(start):
        return (datetime.now() - start._dt).total_seconds()

    def year(self):
        return self._dt.year

    def month(self):
        return self._dt.month

    def day(self):
        return self._dt.day

    def hour(self):
        return self._dt.hour

    def minute(self):
        return self._dt.minute

    def second(self):
        return self._dt.second

    def weekday(self):
        return self._dt.isoweekday()

    def weekdayName(self):
        return self._dt.strftime("%A")

    def monthName(self):
        return self._dt.strftime("%B")

    def format_(self, pattern="YYYY-MM-DD HH:mm:ss"):
        return self._dt.strftime(_strftime_pattern(pattern))

    def plus(self, d):
        return Time(self._dt + timedelta(seconds=d))

    def minus(self, d):
        return Time(self._dt - timedelta(seconds=d))

    def diff(self, other):
        return (self._dt - other._dt).total_seconds()

    def isBefore(self, other):
        return self._dt < other._dt

    def isAfter(self, other):
        return self._dt > other._dt

    def date(self):
        return Time(datetime(self._dt.year, self._dt.month, self._dt.day))

    def toString(self):
        if self._dt.hour == self._dt.minute == self._dt.second == 0 and not self._dt.microsecond:
            return self._dt.strftime("%Y-%m-%d")
        return self._dt.strftime("%Y-%m-%d %H:%M:%S")

    __str__ = toString

    def __eq__(self, other):
        return isinstance(other, Time) and self._dt == other._dt

    def __lt__(self, other):
        return self._dt < other._dt

    def __le__(self, other):
        return self._dt <= other._dt

    def __gt__(self, other):
        return self._dt > other._dt

    def __ge__(self, other):
        return self._dt >= other._dt

    def __hash__(self):
        return hash(self._dt)


# ---------------------------------------------------------------------------
# File and Path
# ---------------------------------------------------------------------------

def _io_error(e: OSError, path: str) -> _rt.Error:
    if isinstance(e, FileNotFoundError):
        return _rt.FileNotFound(f"no such file or folder: {path}")
    if isinstance(e, PermissionError):
        return _rt.PermissionDenied(f"not allowed to use {path}")
    if isinstance(e, IsADirectoryError):
        return _rt.IOError(f"{path} is a folder, not a file")
    return _rt.IOError(f"{path}: {e.strerror or e}")


class File:
    @staticmethod
    def read(path):
        try:
            return _P(path).read_text(encoding="utf-8")
        except OSError as e:
            raise _io_error(e, path) from None
        except UnicodeDecodeError:
            raise _rt.IOError(f"{path} is not a text file (UTF-8)") from None

    @staticmethod
    def readLines(path):
        return File.read(path).splitlines()

    @staticmethod
    def write(path, text):
        try:
            _P(path).write_text(text, encoding="utf-8", newline="")
        except OSError as e:
            raise _io_error(e, path) from None

    @staticmethod
    def writeLines(path, lines):
        File.write(path, "".join(line + "\n" for line in lines))

    @staticmethod
    def append(path, text):
        try:
            with open(path, "a", encoding="utf-8", newline="") as f:
                f.write(text)
        except OSError as e:
            raise _io_error(e, path) from None

    @staticmethod
    def exists(path):
        return _P(path).exists()

    @staticmethod
    def delete(path):
        try:
            _P(path).unlink()
        except OSError as e:
            raise _io_error(e, path) from None

    @staticmethod
    def copy(source, target):
        try:
            shutil.copyfile(source, target)
        except OSError as e:
            raise _io_error(e, source) from None

    @staticmethod
    def move(source, target):
        try:
            shutil.move(source, target)
        except OSError as e:
            raise _io_error(e, source) from None

    @staticmethod
    def size(path):
        try:
            return _P(path).stat().st_size
        except OSError as e:
            raise _io_error(e, path) from None


class Path:
    @staticmethod
    def join(*parts):
        return str(_P(*parts)) if parts else ""

    @staticmethod
    def name(path):
        return _P(path).name

    @staticmethod
    def stem(path):
        return _P(path).stem

    @staticmethod
    def ext(path):
        """The extension without the dot: "notes.txt" -> "txt"."""
        return _P(path).suffix[1:]

    @staticmethod
    def parent(path):
        return str(_P(path).parent)

    @staticmethod
    def absolute(path):
        return str(_P(path).resolve())

    @staticmethod
    def cwd():
        return str(_P.cwd())

    @staticmethod
    def isDir(path):
        return _P(path).is_dir()

    @staticmethod
    def isFile(path):
        return _P(path).is_file()

    @staticmethod
    def listDir(dir="."):  # noqa: A002
        try:
            return sorted(p.name for p in _P(dir).iterdir())
        except OSError as e:
            raise _io_error(e, dir) from None

    @staticmethod
    def walk(dir="."):  # noqa: A002
        root = _P(dir)
        if not root.is_dir():
            raise _rt.FileNotFound(f"no such folder: {dir}")
        return sorted(str(p.relative_to(root)) for p in root.rglob("*") if p.is_file())

    @staticmethod
    def makeDir(path):
        try:
            _P(path).mkdir(parents=True, exist_ok=True)
        except OSError as e:
            raise _io_error(e, path) from None


# ---------------------------------------------------------------------------
# Csv
# ---------------------------------------------------------------------------

class Csv:
    @staticmethod
    def parse(text):
        try:
            reader = csv.DictReader(io.StringIO(text))
            rows = []
            for row in reader:
                if None in row:
                    raise _rt.FormatError(f"row {reader.line_num} has more values than there are columns")
                rows.append({k: (v if v is not None else "") for k, v in row.items()})
            return rows
        except csv.Error as e:
            raise _rt.FormatError(f"not valid CSV: {e}") from None

    @staticmethod
    def read(path):
        return Csv.parse(File.read(path))

    @staticmethod
    def stringify(rows):
        cols: list[str] = []
        for r in rows:
            for k in r:
                if k not in cols:
                    cols.append(k)
        out = io.StringIO()
        w = csv.DictWriter(out, fieldnames=cols, lineterminator="\n")
        w.writeheader()
        for r in rows:
            w.writerow({c: r.get(c, "") for c in cols})
        return out.getvalue()

    @staticmethod
    def write(path, rows):
        File.write(path, Csv.stringify(rows))


# ---------------------------------------------------------------------------
# Json
# ---------------------------------------------------------------------------

def _plain(v):
    """fx3 value -> plain JSON-able Python value."""
    if isinstance(v, Json):
        return v._v
    if v is None or isinstance(v, (bool, int, str)):
        return v
    if isinstance(v, float):
        return None if v != v or v in (math.inf, -math.inf) else v
    if isinstance(v, (list, tuple)):
        return [_plain(x) for x in v]
    if isinstance(v, set):
        try:
            return [_plain(x) for x in sorted(v)]
        except TypeError:
            return [_plain(x) for x in v]
    if isinstance(v, dict):
        return {str(k): _plain(x) for k, x in v.items()}
    if isinstance(v, Time):
        return v.toString()
    if isinstance(v, _rt.Error):
        return {"error": type(v).__name__, "message": v.message}
    if hasattr(v, "__dict__"):
        return {k: _plain(x) for k, x in vars(v).items() if not k.startswith("_")}
    return str(v)


class Json:
    __slots__ = ("_v",)

    def __init__(self, value=None):
        self._v = value

    @staticmethod
    def parse(text):
        try:
            return Json(_json.loads(text))
        except (ValueError, TypeError) as e:
            raise _rt.FormatError(f"not valid JSON: {e}") from None

    @staticmethod
    def stringify(value, pretty=False):
        return _json.dumps(_plain(value), indent=2 if pretty else None, ensure_ascii=False,
                           separators=None if pretty else (",", ":"))

    @staticmethod
    def of(value):
        return Json(_plain(value))

    def get(self, key):
        return Json(self._v.get(key)) if isinstance(self._v, dict) else Json(None)

    def at(self, index):
        if isinstance(self._v, list) and -len(self._v) <= index < len(self._v):
            return Json(self._v[index])
        return Json(None)

    def has(self, key):
        return isinstance(self._v, dict) and key in self._v

    def keys(self):
        return list(self._v.keys()) if isinstance(self._v, dict) else []

    def size(self):
        return len(self._v) if isinstance(self._v, (list, dict, str)) else 0

    def isNull(self):
        return self._v is None

    def isString(self):
        return isinstance(self._v, str)

    def isNumber(self):
        return isinstance(self._v, (int, float)) and not isinstance(self._v, bool)

    def isBool(self):
        return isinstance(self._v, bool)

    def isList(self):
        return isinstance(self._v, list)

    def isObject(self):
        return isinstance(self._v, dict)

    def asString(self):
        return self._v if isinstance(self._v, str) else None

    def asInt(self):
        v = self._v
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v.is_integer():
            return int(v)
        return None

    def asFloat(self):
        v = self._v
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return float(v)
        return None

    def asBool(self):
        return self._v if isinstance(self._v, bool) else None

    def asList(self):
        return [Json(x) for x in self._v] if isinstance(self._v, list) else []

    def toString(self):
        return _json.dumps(self._v, ensure_ascii=False, separators=(",", ":"))

    __str__ = toString

    def __eq__(self, other):
        return isinstance(other, Json) and self._v == other._v

    def __hash__(self):
        return hash(self.toString())


# ---------------------------------------------------------------------------
# Env and Log
# ---------------------------------------------------------------------------

_SECRET_NAME = re.compile(r"KEY|TOKEN|SECRET|PASSWORD|PASSWD|PASS\b|PWD|CREDENTIAL|PRIVATE|AUTH|COOKIE|SESSION",
                          re.IGNORECASE)


class Env:
    @staticmethod
    def get(name):
        v = os.environ.get(name)
        if v in (None, ""):
            return None
        if _SECRET_NAME.search(name):
            _rt.add_secret(v)               # print and Log show it as ****
        return v

    @staticmethod
    def require(name):
        v = Env.get(name)
        if v is None:
            raise _rt.ValueError(f"the environment variable {name} is not set (add it to secrets.env)")
        return v

    @staticmethod
    def has(name):
        return Env.get(name) is not None

    @staticmethod
    def args():
        return [a for a in sys.argv[1:] if a != "--fx3-test"]

    @staticmethod
    def platform():
        return {"darwin": "macos", "win32": "windows"}.get(sys.platform, "linux" if sys.platform.startswith("linux")
                                                           else sys.platform)


class Log:
    _levels = {"debug": 10, "info": 20, "warn": 30, "error": 40}
    _level = 20
    _lock = threading.Lock()

    @staticmethod
    def _write(level: str, message: str) -> None:
        if Log._levels[level] < Log._level:
            return
        stamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with Log._lock:
            sys.stderr.write(f"{stamp} {level.upper():5} {_rt.mask(str(message))}\n")
            sys.stderr.flush()

    @staticmethod
    def debug(message):
        Log._write("debug", message)

    @staticmethod
    def info(message):
        Log._write("info", message)

    @staticmethod
    def warn(message):
        Log._write("warn", message)

    @staticmethod
    def error(message):
        Log._write("error", message)

    @staticmethod
    def level(name):
        if name not in Log._levels:
            raise _rt.Panic(f"Log.level: unknown level '{name}' (use debug, info, warn or error)")
        Log._level = Log._levels[name]


# ---------------------------------------------------------------------------
# Http (client)
# ---------------------------------------------------------------------------

class HttpResponse:
    def __init__(self, status, body, headers):
        self.status = status
        self.body = body
        self.headers = headers

    def json(self):
        return Json.parse(self.body)

    def ok(self):
        return 200 <= self.status < 300

    def __str__(self):
        return f"HttpResponse({self.status}, {len(self.body)} characters)"


_TLS = ssl.create_default_context()          # certificates and host names are always checked
_RETRY_STATUS = {502, 503, 504}


class Http:
    @staticmethod
    def _once(method, url, data, content_type, headers, timeout):
        req = _urlrequest.Request(url, data=data, method=method)
        if data is not None and content_type:
            req.add_header("Content-Type", content_type)
        for k, v in (headers or {}).items():
            req.add_header(k, v)
        try:
            with _urlrequest.urlopen(req, timeout=timeout, context=_TLS) as resp:
                text = resp.read().decode("utf-8", errors="replace")
                return HttpResponse(resp.status, text, dict(resp.headers.items()))
        except _urlerror.HTTPError as e:      # 4xx / 5xx are answers, not failures
            text = e.read().decode("utf-8", errors="replace") if e.fp else ""
            return HttpResponse(e.code, text, dict(e.headers.items()) if e.headers else {})
        except _urlerror.URLError as e:
            reason = e.reason
            if isinstance(reason, TimeoutError) or "timed out" in str(reason):
                raise _rt.TimeoutError(f"{method} {url} timed out") from None
            raise _rt.ConnectionError(f"{method} {url}: {reason}") from None
        except TimeoutError:
            raise _rt.TimeoutError(f"{method} {url} timed out") from None
        except ValueError as e:
            raise _rt.NetworkError(f"bad URL {url}: {e}") from None

    @staticmethod
    def _send(method, url, body=None, content_type=None, headers=None, timeout=30.0, retries=0):
        timeout = float(timeout)
        if not timeout > 0:
            raise _rt.Panic(f"Http: the timeout must be more than 0 seconds, not {_rt.show(timeout)}")
        if retries < 0:
            raise _rt.Panic(f"Http: retries can't be negative ({retries})")
        data = body.encode("utf-8") if body else None
        for attempt in range(retries + 1):
            last = attempt == retries
            try:
                resp = Http._once(method, url, data, content_type, headers, timeout)
            except (_rt.TimeoutError, _rt.ConnectionError):
                if last:
                    raise
            else:
                if resp.status not in _RETRY_STATUS or last:
                    return resp
            _time.sleep(min(8.0, 0.5 * 2 ** attempt) * (0.5 + _random.random()))    # backoff with jitter
        raise AssertionError("unreachable")

    @staticmethod
    def get(url, headers=None, timeout=30.0, retries=2):
        return Http._send("GET", url, headers=headers, timeout=timeout, retries=retries)

    @staticmethod
    def post(url, body="", contentType="application/json", headers=None, timeout=30.0):
        return Http._send("POST", url, body, contentType, headers, timeout)      # never retried: not idempotent

    @staticmethod
    def put(url, body="", contentType="application/json", headers=None, timeout=30.0, retries=2):
        return Http._send("PUT", url, body, contentType, headers, timeout, retries)

    @staticmethod
    def delete(url, headers=None, timeout=30.0, retries=2):
        return Http._send("DELETE", url, headers=headers, timeout=timeout, retries=retries)

    @staticmethod
    def postJson(url, value, headers=None, timeout=30.0):
        return Http._send("POST", url, Json.stringify(value), "application/json", headers, timeout)


# ---------------------------------------------------------------------------
# Server
# ---------------------------------------------------------------------------

class Request:
    def __init__(self, method, path, body, query, params, headers):
        self.method = method
        self.path = path
        self.body = body
        self.query = query
        self.params = params
        self.headers = headers

    def json(self):
        return Json.parse(self.body)

    def param(self, name):
        if name in self.params:
            return self.params[name]
        return self.query.get(name)


class Response:
    def __init__(self, body, status=200, contentType="text/plain; charset=utf-8", headers=None):
        self.status = status
        self.body = body
        self.contentType = contentType
        self.headers = headers or {}

    @staticmethod
    def text(body, status=200):
        return Response(body, status)

    @staticmethod
    def json(value, status=200):
        return Response(Json.stringify(value), status, "application/json")

    @staticmethod
    def html(body, status=200):
        return Response(body, status, "text/html; charset=utf-8")

    @staticmethod
    def notFound(message="not found"):
        return Response(Json.stringify({"error": message}), 404, "application/json")

    @staticmethod
    def error(message, status=500):
        return Response(Json.stringify({"error": _rt.mask(message)}), status, "application/json")

    @staticmethod
    def redirect(url):
        return Response("", 302, "text/plain", {"Location": url})


def _compile_route(path: str):
    names: list[str] = []

    def repl(m):
        names.append(m.group(1))
        return rf"(?P<{m.group(1)}>[^/]+)"
    pattern = re.sub(r"\{(\w+)\}", repl, re.escape(path).replace(r"\{", "{").replace(r"\}", "}"))
    return re.compile("^" + pattern + "/?$"), names


class Server:
    def __init__(self, port=8080):
        self.port = int(os.environ.get("SERVER_PORT") or port)
        self._routes: list[tuple[str, re.Pattern, object]] = []
        self._httpd = None
        self._thread = None
        self._max_body = 1024 * 1024
        self._timeout = 30.0
        self._origins: list[str] = []
        self._required: tuple[str, str, list[str]] | None = None
        self._access_log = True

    @staticmethod
    def create(port=8080):
        return Server(port)

    # ---- settings -------------------------------------------------------------
    def limits(self, maxBodyKb=1024, timeout=30.0):
        if maxBodyKb <= 0 or float(timeout) <= 0:
            raise _rt.Panic("Server.limits: the body size and the timeout must be more than 0")
        self._max_body, self._timeout = int(maxBodyKb) * 1024, float(timeout)

    def allowOrigins(self, origins):
        self._origins = list(origins)

    def requireHeader(self, name, value, open=None):  # noqa: A002
        if not value:
            raise _rt.Panic(f"Server.requireHeader: the value for {name} is empty")
        _rt.add_secret(value)
        self._required = (name, value, list(open or []))

    def accessLog(self, on):
        self._access_log = bool(on)

    # ---- routes -----------------------------------------------------------------
    def _add(self, method, path, handler):
        regex, _ = _compile_route(path)
        self._routes.append((method, regex, handler))

    def get(self, path, h):
        self._add("GET", path, h)

    def post(self, path, h):
        self._add("POST", path, h)

    def put(self, path, h):
        self._add("PUT", path, h)

    def delete(self, path, h):
        self._add("DELETE", path, h)

    def _cors(self, headers):
        origin = headers.get("Origin") or headers.get("origin")
        if not origin or not self._origins:
            return {}
        if "*" in self._origins:
            return {"Access-Control-Allow-Origin": "*"}
        if origin in self._origins:
            return {"Access-Control-Allow-Origin": origin, "Vary": "Origin"}
        return {}

    def _authorised(self, path, headers) -> bool:
        if self._required is None:
            return True
        name, value, open_paths = self._required
        if path in open_paths:
            return True
        got = next((v for k, v in headers.items() if k.lower() == name.lower()), "")
        return hmac.compare_digest(got.encode(), value.encode())

    def _dispatch(self, method, raw_path, body, headers):
        parts = _urlparse.urlsplit(raw_path)
        query = {k: v[0] for k, v in _urlparse.parse_qs(parts.query).items()}
        path = parts.path or "/"
        if method == "OPTIONS":                 # CORS preflight
            cors = self._cors(headers)
            if not cors:
                return Response("", 403)
            return Response("", 204, headers={**cors, "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE",
                                              "Access-Control-Allow-Headers": "*", "Access-Control-Max-Age": "600"})
        if not self._authorised(path, headers):
            return Response.error("unauthorised", 401)
        allowed = False
        for m, regex, handler in self._routes:
            match = regex.match(path)
            if not match:
                continue
            allowed = True
            if m != method and not (method == "HEAD" and m == "GET"):
                continue
            req = Request(method, path, body, query, {k: _urlparse.unquote(v) for k, v in match.groupdict().items()},
                          headers)
            try:
                resp = handler(req)
            except _rt.Error as e:
                Log.warn(f"{method} {path} failed: {e}")
                return Response.error(e.message or type(e).__name__, 500)
            except Exception as e:  # noqa: BLE001 - a bug in a handler must not stop the server
                Log.error(f"{method} {path}: {_rt._panic_message(e) or repr(e)}{_rt.origin(e)}")
                return Response.error("internal error", 500)
            if not isinstance(resp, Response):
                return Response.error("the handler didn't return a Response", 500)
            return resp
        if allowed:
            return Response.error("method not allowed", 405)
        return Response.notFound()

    def _log(self, method, path, status, started):
        if self._access_log:
            line = {"method": method, "path": path, "status": status,
                    "ms": round((_time.perf_counter() - started) * 1000, 1)}
            Log.info("access " + _json.dumps(line))       # the query string is left out: it may hold tokens

    def start(self):
        from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
        if self._httpd is not None:
            return
        server = self

        class _Handler(BaseHTTPRequestHandler):
            timeout = server._timeout             # a slow client can't hold a thread forever

            def _send(self, resp):
                data = resp.body.encode("utf-8")
                self.send_response(resp.status)
                self.send_header("Content-Type", resp.contentType)
                self.send_header("Content-Length", str(len(data)))
                self.send_header("X-Content-Type-Options", "nosniff")
                headers = {**server._cors(dict(self.headers.items())), **resp.headers}
                for k, v in headers.items():
                    self.send_header(k, v)
                self.end_headers()
                if self.command != "HEAD":
                    self.wfile.write(data)

            def _handle(self):
                started = _time.perf_counter()
                path = _urlparse.urlsplit(self.path).path or "/"
                try:
                    length = int(self.headers.get("Content-Length") or 0)
                except ValueError:
                    length = -1
                if length < 0 or length > server._max_body:
                    resp = Response.error("request body too large" if length > 0 else "bad Content-Length",
                                          413 if length > 0 else 400)
                    self.close_connection = True       # the body is never read
                else:
                    body = self.rfile.read(length).decode("utf-8", errors="replace") if length else ""
                    resp = server._dispatch(self.command, self.path, body, dict(self.headers.items()))
                server._log(self.command, path, resp.status, started)
                self._send(resp)

            do_GET = do_POST = do_PUT = do_DELETE = do_HEAD = do_OPTIONS = _handle  # noqa: N815

            def log_message(self, fmt, *args):
                pass                                # the access log above replaces this

        class _HTTPServer(ThreadingHTTPServer):
            daemon_threads = False                  # stop() waits for requests in progress
            block_on_close = True

        host = os.environ.get("SERVER_HOST", "127.0.0.1")
        try:
            self._httpd = _HTTPServer((host, self.port), _Handler)
        except OSError as e:
            raise _rt.Panic(f"can't start the server on port {self.port}: {e.strerror or e}") from None
        self.port = self._httpd.server_address[1]
        self._thread = threading.Thread(target=self._httpd.serve_forever, daemon=True)
        self._thread.start()

    def stop(self):
        if self._httpd is not None:
            self._httpd.shutdown()                  # no new requests
            self._httpd.server_close()              # waits for the ones in progress
            self._httpd = None

    def keepRunning(self):
        self.start()
        Log.info(f"serving on http://{os.environ.get('SERVER_HOST', '127.0.0.1')}:{self.port}  (Ctrl+C to stop)")
        stopping = threading.Event()

        def on_signal(signum, frame):
            stopping.set()
        try:
            signal.signal(signal.SIGTERM, on_signal)    # containers stop programs with SIGTERM
        except (ValueError, AttributeError, OSError):
            pass                                    # not the main thread, or no SIGTERM here
        try:
            while not stopping.wait(1.0):
                pass
        except KeyboardInterrupt:
            pass
        Log.info("stopping: finishing the requests in progress")
        self.stop()
        Log.info("stopped")


# ---------------------------------------------------------------------------
# Db (SQLite)
# ---------------------------------------------------------------------------

def _db_value(v):
    if isinstance(v, (Time,)):
        return v.toString()
    if isinstance(v, Json):
        return v.toString()
    if isinstance(v, (list, dict, set, tuple)):
        return Json.stringify(v)
    return v


class Db:
    def __init__(self, conn):
        self._conn = conn
        self._lock = threading.RLock()
        self._tx = 0                        # > 0 inside a transaction (held by one thread)
        self._last_id = 0

    @staticmethod
    def open(path):  # noqa: A003
        try:
            conn = sqlite3.connect(path, check_same_thread=False, isolation_level=None)   # we say when transactions are
            conn.row_factory = sqlite3.Row
            conn.execute("PRAGMA foreign_keys = ON")
            return Db(conn)
        except sqlite3.Error as e:
            raise _rt.IOError(f"can't open the database {path}: {e}") from None

    def _run(self, sql, params):
        try:
            with self._lock:
                return self._conn.execute(sql, [_db_value(p) for p in (params or [])])
        except sqlite3.Error as e:
            raise _rt.DbError(f"{e} (in: {sql.strip()[:80]})") from None

    def exec(self, sql, params=None):  # noqa: A003
        cur = self._run(sql, params)
        self._last_id = cur.lastrowid or self._last_id
        return cur.rowcount if cur.rowcount is not None and cur.rowcount >= 0 else 0

    def query(self, sql, params=None):
        cur = self._run(sql, params)
        return [{k: Json(row[k]) for k in row.keys()} for row in cur.fetchall()]

    def queryOne(self, sql, params=None):
        rows = self.query(sql, params)
        return rows[0] if rows else None

    def lastId(self):
        return self._last_id

    def close(self):
        self._conn.close()

    # ---- transactions -------------------------------------------------------------
    def begin(self):
        self._lock.acquire()                # other threads wait until commit / rollback
        try:
            self._conn.execute("BEGIN")
        except sqlite3.Error as e:
            self._lock.release()
            raise _rt.DbError(f"can't start a transaction: {e}") from None
        self._tx += 1

    def _end(self, sql):
        if self._tx == 0:
            return False
        try:
            self._conn.execute(sql)
        finally:
            self._tx -= 1
            self._lock.release()
        return True

    def commit(self):
        try:
            if not self._end("COMMIT"):
                raise _rt.DbError("commit without begin")
        except sqlite3.Error as e:
            raise _rt.DbError(f"commit failed: {e}") from None

    def rollback(self):
        try:
            self._end("ROLLBACK")
        except sqlite3.Error:
            pass                            # nothing left to undo

    def transaction(self, work):
        self.begin()
        try:
            work()
        except BaseException as e:
            self.rollback()
            if isinstance(e, _rt.DbError):
                raise
            if isinstance(e, _rt.Error):
                raise _rt.DbError(f"rolled back: {e.message or type(e).__name__}") from None
            raise                           # a panic stays a panic, after the rollback
        self.commit()

    def migrate(self, folder):
        try:
            files = sorted(f for f in _P(folder).iterdir() if f.suffix == ".sql" and f.is_file())
        except OSError as e:
            raise _io_error(e, folder) from None
        self.exec("create table if not exists fx3_migrations (name text primary key, applied text not null)")
        done = {r["name"].asString() for r in self.query("select name from fx3_migrations")}
        applied = 0
        for f in files:
            if f.name in done:
                continue
            try:
                sql = f.read_text(encoding="utf-8")
            except OSError as e:
                raise _io_error(e, str(f)) from None
            with self._lock:
                try:
                    self._conn.executescript("BEGIN;\n" + sql + "\n;")
                    self._conn.execute("insert into fx3_migrations (name, applied) values (?, ?)",
                                       [f.name, datetime.now().isoformat(timespec="seconds")])
                    self._conn.execute("COMMIT")
                except sqlite3.Error as e:
                    if self._conn.in_transaction:
                        self._conn.execute("ROLLBACK")
                    raise _rt.DbError(f"migration {f.name} failed and was rolled back: {e}") from None
            applied += 1
        return applied


# ---------------------------------------------------------------------------
# Ai (Claude, while the program runs)
# ---------------------------------------------------------------------------

_FALLBACK_BETA = "server-side-fallback-2026-07-01"


class Ai:
    _client = None

    @staticmethod
    def _get_client():
        if Ai._client is None:
            try:
                import anthropic
            except ImportError:
                raise _rt.AiError("the Ai module needs the `anthropic` package: pip install anthropic") from None
            Ai._client = anthropic.Anthropic()
        return Ai._client

    @staticmethod
    def _call(model, system, prompt, output_config=None):
        client = Ai._get_client()
        import anthropic
        kwargs = dict(model=model or "claude-opus-5-5", max_tokens=16000,
                      messages=[{"role": "user", "content": prompt}],
                      betas=[_FALLBACK_BETA], fallbacks="default")
        if system:
            kwargs["system"] = system
        if output_config:
            kwargs["output_config"] = output_config
        try:
            msg = client.beta.messages.create(**kwargs)
        except TypeError as e:
            if "authentication" in str(e).lower():
                raise _rt.AiError("no ANTHROPIC_API_KEY: add it to secrets.env") from None
            raise
        except anthropic.AuthenticationError:
            raise _rt.AiError("the Anthropic API rejected the API key") from None
        except anthropic.RateLimitError:
            raise _rt.AiError("rate limited by the Anthropic API; try again later") from None
        except anthropic.APIStatusError as e:
            raise _rt.AiError(f"Anthropic API error {e.status_code}: {e.message}") from None
        except anthropic.APIConnectionError:
            raise _rt.AiError("can't reach the Anthropic API") from None
        if msg.stop_reason == "refusal":
            raise _rt.AiError("the model declined to answer")
        return "".join(b.text for b in msg.content if b.type == "text")

    @staticmethod
    def ask(prompt, system="", model="claude-opus-5-5"):
        return Ai._call(model, system, prompt).strip()

    @staticmethod
    def classify(text, options, instructions="", model="claude-opus-5-5"):
        if not options:
            raise _rt.Panic("Ai.classify needs at least one option")
        schema = {"type": "object", "additionalProperties": False, "required": ["answer"],
                  "properties": {"answer": {"type": "string", "enum": list(options)}}}
        prompt = (instructions + "\n\n" if instructions else "") + \
            "Choose the option that fits best.\n\nText:\n" + text
        out = Ai._call(model, "", prompt, {"format": {"type": "json_schema", "schema": schema}})
        try:
            return _json.loads(out)["answer"]
        except (ValueError, KeyError):
            raise _rt.AiError("the model's answer was not one of the options") from None


# ---------------------------------------------------------------------------
# Schedule
# ---------------------------------------------------------------------------

class _Job:
    def __init__(self, name, interval, work, at):
        self.name, self.interval, self.work, self.at = name, interval, work, at


class Schedule:
    _jobs: list[_Job] = []
    _state: dict[str, str] | None = None

    @staticmethod
    def _state_file():
        return _P(os.environ.get("SCHEDULE_STATE") or ".fx3-schedule.json")

    @staticmethod
    def _load():
        if Schedule._state is None:
            try:
                Schedule._state = dict(_json.loads(Schedule._state_file().read_text(encoding="utf-8")))
            except (OSError, ValueError):
                Schedule._state = {}
        return Schedule._state

    @staticmethod
    def _save():
        f = Schedule._state_file()
        tmp = f.with_name(f.name + ".tmp")
        try:
            tmp.write_text(_json.dumps(Schedule._load(), indent=2, sort_keys=True), encoding="utf-8")
            os.replace(tmp, f)                  # never a half-written file
        except OSError as e:
            Log.warn(f"Schedule: can't save the last runs to {f}: {e}")

    @staticmethod
    def every(interval, work, at="", name=""):
        interval = float(interval)
        if interval <= 0:
            raise _rt.Panic(f"Schedule.every: the interval must be more than 0, not {_rt.show_duration(interval)}")
        if at:
            m = re.fullmatch(r"(\d{1,2}):(\d{2})", at)
            if not m or int(m.group(1)) > 23 or int(m.group(2)) > 59:
                raise _rt.Panic(f'Schedule.every: at must be "HH:MM" (24-hour), not "{at}"')
            if interval % 86400:
                raise _rt.Panic("Schedule.every: `at` needs an interval of whole days (1d, 7d, ...)")
            at = (int(m.group(1)), int(m.group(2)))
        name = name or f"job {len(Schedule._jobs) + 1}"
        if any(j.name == name for j in Schedule._jobs):
            raise _rt.Panic(f'Schedule.every: there is already a job called "{name}"')
        Schedule._jobs.append(_Job(name, interval, work, at or None))

    @staticmethod
    def _next(job, now):
        """When the job is due next. Never run -> now (or today's / tomorrow's `at`). Missed runs -> now, once."""
        last = Schedule._load().get(job.name)
        last_dt = datetime.fromisoformat(last) if last else None
        if job.at is None:
            return now if last_dt is None else last_dt + timedelta(seconds=job.interval)
        h, m = job.at
        if last_dt is None:
            today = now.replace(hour=h, minute=m, second=0, microsecond=0)
            return today if today >= now - timedelta(minutes=1) else today + timedelta(days=1)
        # after downtime this is in the past: the job runs once, and the next run counts from then
        return last_dt.replace(hour=h, minute=m, second=0, microsecond=0) + timedelta(seconds=job.interval)

    @staticmethod
    def _run_job(job):
        started = datetime.now()
        try:
            job.work()
        except Exception as e:  # noqa: BLE001 - one failing job must not stop the others
            Log.error(f'Schedule: job "{job.name}" failed: {_rt._panic_message(e) or e}{_rt.origin(e)}')
        Schedule._load()[job.name] = started.isoformat(timespec="seconds")
        Schedule._save()

    @staticmethod
    def runPending():
        now = datetime.now()
        due = [j for j in Schedule._jobs if Schedule._next(j, now) <= now]
        for job in due:
            Schedule._run_job(job)
        return len(due)

    @staticmethod
    def run():
        if not Schedule._jobs:
            raise _rt.Panic("Schedule.run: no jobs; add them with Schedule.every first")
        stopping = threading.Event()
        try:
            signal.signal(signal.SIGTERM, lambda signum, frame: stopping.set())
        except (ValueError, AttributeError, OSError):
            pass
        Log.info("Schedule: " + ", ".join(f'"{j.name}" every {_rt.show_duration(j.interval)}'
                                          + (f" at {j.at[0]:02d}:{j.at[1]:02d}" if j.at else "")
                                          for j in Schedule._jobs) + "  (Ctrl+C to stop)")
        try:
            while not stopping.is_set():
                Schedule.runPending()
                now = datetime.now()
                wait = min((Schedule._next(j, now) - now).total_seconds() for j in Schedule._jobs)
                stopping.wait(max(1.0, min(wait, 60.0)))      # wake up at least every minute (clock changes)
        except KeyboardInterrupt:
            pass
        Log.info("Schedule: stopped")


# ---------------------------------------------------------------------------
# Process (never through a shell)
# ---------------------------------------------------------------------------

class ProcessResult:
    def __init__(self, code, out, err):
        self.code, self.out, self.err = code, out, err

    def ok(self):
        return self.code == 0

    def __str__(self):
        return f"ProcessResult(code {self.code})"


class Process:
    @staticmethod
    def run(command, input_="", timeout=60.0):     # `input` is spelled input_ in generated code
        import subprocess
        command = [str(c) for c in command]
        if not command or not command[0]:
            raise _rt.Panic("Process.run: the command is empty (write the program, then its arguments)")
        timeout = float(timeout)
        if not timeout > 0:
            raise _rt.Panic(f"Process.run: the timeout must be more than 0 seconds, not {_rt.show(timeout)}")
        try:
            done = subprocess.run(command, input=input_, capture_output=True, text=True, timeout=timeout,  # noqa: S603
                                  shell=False, check=False, encoding="utf-8", errors="replace")
        except FileNotFoundError:
            raise _rt.IOError(f"no program called {command[0]}") from None
        except PermissionError:
            raise _rt.IOError(f"{command[0]} can't be run (permission denied)") from None
        except subprocess.TimeoutExpired:
            raise _rt.TimeoutError(f"{command[0]} didn't finish within {_rt.show_duration(timeout)}") from None
        except OSError as e:
            raise _rt.IOError(f"can't run {command[0]}: {e}") from None
        return ProcessResult(done.returncode, done.stdout or "", done.stderr or "")


# ---------------------------------------------------------------------------
# Email
# ---------------------------------------------------------------------------

class Email:
    @staticmethod
    def send(to, subject, body):
        import smtplib
        from email.message import EmailMessage
        host = Env.get("SMTP_HOST")
        if host is None:
            raise _rt.NetworkError("SMTP_HOST is not set (add the SMTP_* settings to secrets.env)")
        port = int(Env.get("SMTP_PORT") or 587)
        sender = Env.get("SMTP_FROM") or Env.get("SMTP_USER") or "fx3@localhost"
        msg = EmailMessage()
        msg["From"], msg["To"], msg["Subject"] = sender, to, subject
        msg.set_content(body)
        try:
            smtp_cls = smtplib.SMTP_SSL if port == 465 else smtplib.SMTP
            with smtp_cls(host, port, timeout=30) as smtp:
                if port == 587:
                    smtp.starttls()
                if Env.get("SMTP_USER"):
                    smtp.login(Env.get("SMTP_USER"), Env.get("SMTP_PASSWORD") or "")
                smtp.send_message(msg)
        except (OSError, smtplib.SMTPException) as e:
            raise _rt.NetworkError(f"couldn't send the email to {to}: {e}") from None
